KG42.register("rules-8e125999eaa332e8557a42e7",{"id":"42-data_center_space_time_flexibility::v141-c-R017","paper":"42-data_center_space_time_flexibility","record":{"rule_id":"v141-c-R017","mechanism_id":"v141-a-M05","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"The demand quantity submitted for each time limits the load cleared for that time in the temporal welfare formulation. Scope: The single-spatial-node temporal market; requested load at each time. The supply quantity submitted for each time limits generation cleared for that time in the temporal welfare formulation. Scope: The single-spatial-node temporal market; generation at each time. The temporal welfare formulation minimizes generation and virtual-link costs minus bid-valued served demand. Scope: General temporal virtual-link clearing with one spatial node. Net physical load must remain between zero and the time-specific computing capacity, and each virtual flow must remain within its capacity. Scope: Computing and virtual-link feasibility at each time in temporal welfare clearing.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","clearing.social_welfare"],"E":[{"edge_id":"v141-c-R017-E001","source":"bidding.demand","target":"clearing.social_welfare","type":"limits","constraint_ids":["v141-c-R017-C001"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"edge_id":"v141-c-R017-E002","source":"bidding.supply","target":"clearing.social_welfare","type":"limits","constraint_ids":["v141-c-R017-C002"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Computing and virtual-link feasibility at each time in temporal welfare clearing. | General temporal virtual-link clearing with one spatial node. | The single-spatial-node temporal market; generation at each time. | The single-spatial-node temporal market; requested load at each time.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},"x":[{"variable_id":"v141-c-R017-x-d_t","symbol":"d_t","meaning":"Load cleared/withdrawn at time t in the single-spatial-node temporal welfare formulation.","kind":"operational","domain":"d_t \\in \\mathbb{R}_{\\ge 0}, with 0 \\le d_t \\le \\bar d_t for each t \\in T (source (2.31e)).","unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"variable_id":"v141-c-R017-x-p_t","symbol":"p_t","meaning":"Generation cleared at time t in the single-spatial-node temporal welfare formulation.","kind":"operational","domain":"p_t \\in \\mathbb{R}_{\\ge 0}, with 0 \\le p_t \\le \\bar p_t for each t \\in T (source (2.31d)).","unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"variable_id":"v141-c-R017-x-delta_v","symbol":"\\delta_v","meaning":"Cleared temporal virtual-link load-shift flow for virtual link v.","kind":"operational","domain":"\\delta_v \\in \\mathbb{R}_{\\ge 0}, with 0 \\le \\delta_v \\le \\bar\\delta_v for each v \\in V (source (2.31f)).","unit":null,"indices":["v"],"evidence_ids":["v141-b-g02-e037"]}],"theta":[{"parameter_id":"v141-c-R017-theta-alpha_p_t","symbol":"\\alpha^{p}_t","meaning":"Supplier bid price at time t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"parameter_id":"v141-c-R017-theta-bar_p_t","symbol":"\\bar p_t","meaning":"Supplier offered capacity at time t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"parameter_id":"v141-c-R017-theta-alpha_delta_v","symbol":"\\alpha^{\\delta}_v","meaning":"Bid price of temporal virtual link v.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["v"],"evidence_ids":["v141-b-g02-e034","v141-b-g02-e037"]},{"parameter_id":"v141-c-R017-theta-bar_delta_v","symbol":"\\bar\\delta_v","meaning":"Capacity of temporal virtual link v as printed in (2.31f).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["v"],"evidence_ids":["v141-b-g02-e037"]},{"parameter_id":"v141-c-R017-theta-alpha_d_t","symbol":"\\alpha^{d}_t","meaning":"DaCe demand bid price at time t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e033"]},{"parameter_id":"v141-c-R017-theta-bar_d_t","symbol":"\\bar d_t","meaning":"Amount of load requested by the DaCe at time t (requested-load capacity).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"parameter_id":"v141-c-R017-theta-bar_d_max_t","symbol":"\\bar d^{max}_t","meaning":"Time-specific computing capacity appearing in (2.31c); the temporal section does not separately define it.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e037"]}],"phi":[{"constraint_id":"v141-c-R017-C001","kind":"mathematical","role":"core","statement":"The demand quantity submitted for each time limits the load cleared for that time in the temporal welfare formulation. Scope: The single-spatial-node temporal market; requested load at each time.","expression":"0 \\le d_t \\le \\bar d_t, \\quad \\forall t \\in T","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.social_welfare"],"variable_refs":["v141-c-R017-x-d_t"],"parameter_refs":["v141-c-R017-theta-bar_d_t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"constraint_id":"v141-c-R017-C002","kind":"mathematical","role":"core","statement":"The supply quantity submitted for each time limits generation cleared for that time in the temporal welfare formulation. Scope: The single-spatial-node temporal market; generation at each time.","expression":"0 \\le p_t \\le \\bar p_t, \\quad \\forall t \\in T","formalization_origin":"source","template_id":null,"members":["bidding.supply","clearing.social_welfare"],"variable_refs":["v141-c-R017-x-p_t"],"parameter_refs":["v141-c-R017-theta-bar_p_t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"constraint_id":"v141-c-R017-C003","kind":"mathematical","role":"core","statement":"The temporal welfare formulation minimizes generation and virtual-link costs minus bid-valued served demand. Scope: General temporal virtual-link clearing with one spatial node.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"]},{"constraint_id":"v141-c-R017-C004","kind":"mathematical","role":"core","statement":"Net physical load must remain between zero and the time-specific computing capacity, and each virtual flow must remain within its capacity. Scope: Computing and virtual-link feasibility at each time in temporal welfare clearing.","expression":"0 \\le d_t + \\sum_{v\\in V^{rec}_t}\\delta_v - \\sum_{v\\in V^{snd}_t}\\delta_v \\le \\bar d^{max}_t, \\quad \\forall t\\in T; \\qquad 0 \\le \\delta_v \\le \\bar\\delta_v, \\quad \\forall v\\in V","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R017-x-d_t","v141-c-R017-x-delta_v"],"parameter_refs":["v141-c-R017-theta-bar_d_max_t","v141-c-R017-theta-bar_delta_v"],"evidence_ids":["v141-b-g02-e037"]},{"constraint_id":"v141-c-R017-C005","kind":"mathematical","role":"core","statement":"At each time, generation cleared equals load cleared plus virtual-link inflows minus virtual-link outflows. Scope: Time-node power balance in the single-spatial-node temporal welfare formulation.","expression":"p_t = d_t + \\sum_{v\\in V^{in}_t}\\delta_v - \\sum_{v\\in V^{out}_t}\\delta_v, \\quad \\forall t\\in T","formalization_origin":"source","template_id":null,"members":["bidding.demand","bidding.supply","clearing.social_welfare"],"variable_refs":["v141-c-R017-x-p_t","v141-c-R017-x-d_t","v141-c-R017-x-delta_v"],"parameter_refs":[],"evidence_ids":["v141-b-g02-e037"]}],"pi":[{"evidence_id":"v141-b-g02-e033","location":{"location_id":"src-1c03246cb9-p08-c1r4__v141-a-M05-participation","page":8,"printed_page":null,"section":"2.6 Basic formulation with general virtual links (temporal)","anchor_text":"model, we consider a time horizon given by the time nodes  = te {𝑡1, 𝑡2, … , 𝑡𝑇}. For simplicity, w","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"To see how to incorporate temporal virtual links in the clearing model, we consider a time horizon given by the time nodes T=\\{t_1,t_2,\\ldots,t_T\\}. For simplicity, we consider a network with a single spatial node (no transmission network is present in this setting). For each time node t\\in T, the DaCe bids a price \\alpha^{d}_t and a capacity \\bar d_t that represents the amount of load requested. Similarly, we consider a supplier that bids a price \\alpha^{p}_t and a capacity \\bar p_t at time t\\in T. The clearing formulation will find optimal levels for load satisfaction d_t and generation p_t for each time t\\in T."},{"evidence_id":"v141-b-g02-e037","location":{"location_id":"src-1c03246cb9-p08-c2r2__v141-a-M05-clearing","page":8,"printed_page":null,"section":"2.6 Basic formulation with general virtual links (temporal)","anchor_text":"∑ ∑ ∑ b) min 𝛼𝑝𝑡𝑝𝑡+ 𝛼𝛿𝑣𝛿𝑣− 𝛼𝑑𝑗𝑑𝑗 (2.31a) 𝑑,𝑝,𝛿 𝑡∈ 𝑣∈ 𝑗∈ ∑ ∑ c) s.t. 𝑝𝑡= 𝑑𝑡+ 𝛿𝑣− 𝛿𝑣, 𝑡∈ (2.31b) 𝑣","equation_id":"2.31","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"The clearing formulation for this setting is: min_{d,p,\\delta}\\sum_{t\\in T}\\alpha^{p}_t p_t+\\sum_{v\\in V}\\alpha^{\\delta}_v\\delta_v-\\sum_{j\\in D}\\alpha^{d}_j d_j (2.31a) s.t. p_t=d_t+\\sum_{v\\in V^{in}_t}\\delta_v-\\sum_{v\\in V^{out}_t}\\delta_v, t\\in T (2.31b); 0\\le d_t+\\sum_{v\\in V^{rec}_t}\\delta_v-\\sum_{v\\in V^{snd}_t}\\delta_v\\le\\bar d^{max}_t, (\\omega^{l}_t,\\omega^{u}_t) t\\in T (2.31c); 0\\le p_t\\le\\bar p_t, t\\in T (2.31d); 0\\le d_t\\le\\bar d_t, t\\in T (2.31e); 0\\le\\delta_v\\le\\bar\\delta_v, v\\in V (2.31f)."},{"evidence_id":"v141-b-g02-e034","location":{"location_id":"src-1c03246cb9-p08-c1r4__v141-a-M05-bidding","page":8,"printed_page":null,"section":"2.6 Basic formulation with general virtual links (temporal)","anchor_text":"model, we consider a time horizon given by the time nodes  = te {𝑡1, 𝑡2, … , 𝑡𝑇}. For simplicity, w","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Each virtual link v\\in V branches from a time node t to a later time node t'. The virtual link bids into the market at a price \\alpha^{\\delta}_v and capacity \\bar\\delta_t. The load at each time t\\in T is associated with a set of virtual links V_t\\subseteq V. For each v\\in V_t, we have snd(v)=t (since each consumer can only bid flexibility going from the current time to a later time). The market clearing process will find the optimal time shift flows \\delta_v for each v\\in V. A distinguishing feature of temporal virtual links (compared to spatial virtual links) is that they are naturally unidirectional."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M05-bidding","v141-a-M05-clearing","v141-a-M05-participation"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e033","quote":"For each time node t\\in T, the DaCe bids a price \\alpha^{d}_t and a capacity \\bar d_t that represents the amount of load requested."},{"evidence_id":"v141-b-g02-e037","quote":"0\\le d_t\\le\\bar d_t, t\\in T (2.31e)"}],[{"evidence_id":"v141-b-g02-e033","quote":"Similarly, we consider a supplier that bids a price \\alpha^{p}_t and a capacity \\bar p_t at time t\\in T."},{"evidence_id":"v141-b-g02-e037","quote":"0\\le p_t\\le\\bar p_t, t\\in T (2.31d)"}],[{"evidence_id":"v141-b-g02-e037","quote":"The clearing formulation for this setting is: min_{d,p,\\delta}\\sum_{t\\in T}\\alpha^{p}_t p_t+\\sum_{v\\in V}\\alpha^{\\delta}_v\\delta_v-\\sum_{j\\in D}\\alpha^{d}_j d_j (2.31a)"},{"evidence_id":"v141-b-g02-e033","quote":"For simplicity, we consider a network with a single spatial node (no transmission network is present in this setting)."}],[{"evidence_id":"v141-b-g02-e037","quote":"0\\le d_t+\\sum_{v\\in V^{rec}_t}\\delta_v-\\sum_{v\\in V^{snd}_t}\\delta_v\\le\\bar d^{max}_t, (\\omega^{l}_t,\\omega^{u}_t) t\\in T (2.31c)"},{"evidence_id":"v141-b-g02-e037","quote":"0\\le\\delta_v\\le\\bar\\delta_v, v\\in V (2.31f)"}]],"C2_formalization":{"graph_sha256":"fb88f0211164333e753c41a66162a4e11b8ec6452efb6a3d5735ed1dc73f0a89","applicability":"needs_revision","reason":"Partial source-grounded formalization. C001, C002, C004 and added C005 are transcribed from (2.31b)-(2.31f): C001 is 0 \u003c= d_t \u003c= bar d_t; C002 is 0 \u003c= p_t \u003c= bar p_t; C004 is the conjunction of (2.31c) and (2.31f); C005 is the time-node balance (2.31b). The social-welfare objective C003 is not formalized because the printed (2.31a) demand term is sum_{j in D} alpha^d_j d_j, while the temporal text defines time-indexed alpha^d_t and d_t and bounds d_t in (2.31e); substituting t for j would change a source index. In addition, bar d^max_t is used in (2.31c) without a separate temporal definition. B evidence remains unreviewed; no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R017-x-d_t","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R017-E001"],"rationale":"d_t is the load cleared in the social-welfare formulation; its upper bound bar d_t comes from the DaCe demand bid through the frozen limits edge E001."},{"object_id":"v141-c-R017-x-p_t","node_ids":["bidding.supply","clearing.social_welfare"],"edge_ids":["v141-c-R017-E002"],"rationale":"p_t is the generation cleared in the social-welfare formulation; its upper bound bar p_t comes from the supplier bid through the frozen limits edge E002."},{"object_id":"v141-c-R017-x-delta_v","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"delta_v is an internal temporal virtual-flow decision of the clearing formulation. The frozen V/E inventory has no virtual-link node or edge, so it is bound only to the clearing node."},{"object_id":"v141-c-R017-theta-alpha_p_t","node_ids":["bidding.supply","clearing.social_welfare"],"edge_ids":["v141-c-R017-E002"],"rationale":"alpha^p_t is the time-indexed supplier bid price entering the welfare objective; it is associated with the supply-to-clearing limits edge E002."},{"object_id":"v141-c-R017-theta-bar_p_t","node_ids":["bidding.supply","clearing.social_welfare"],"edge_ids":["v141-c-R017-E002"],"rationale":"bar p_t is the time-indexed supplier offered capacity; it is the supply-side parameter limiting p_t through edge E002."},{"object_id":"v141-c-R017-theta-alpha_delta_v","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"alpha^delta_v is the bid price of temporal virtual link v in the clearing objective. The frozen graph has no virtual-link node/edge, so it is attached only to clearing.social_welfare."},{"object_id":"v141-c-R017-theta-bar_delta_v","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"bar delta_v is the per-virtual-link capacity in (2.31f); it is an internal clearing parameter attached to clearing.social_welfare because the frozen graph has no virtual-link node."},{"object_id":"v141-c-R017-theta-alpha_d_t","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R017-E001"],"rationale":"alpha^d_t is the time-indexed DaCe demand bid price; it is associated with the demand-to-clearing limits edge E001. Its objective use is not formalized because of the j/t index mismatch in (2.31a)."},{"object_id":"v141-c-R017-theta-bar_d_t","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R017-E001"],"rationale":"bar d_t is the requested-load capacity in the DaCe bid and the upper bound on d_t in (2.31e), relating demand bidding to welfare clearing through E001."},{"object_id":"v141-c-R017-theta-bar_d_max_t","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"bar d^max_t is the time-specific computing capacity used in (2.31c). It is internal to clearing feasibility; the frozen graph has no computing-capacity node, so it is attached to clearing.social_welfare."},{"object_id":"v141-c-R017-C001","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R017-E001"],"rationale":"C001 formalizes the demand-limit relation: the requested-load capacity bar d_t bounds the cleared load d_t at each time."},{"object_id":"v141-c-R017-C002","node_ids":["bidding.supply","clearing.social_welfare"],"edge_ids":["v141-c-R017-E002"],"rationale":"C002 formalizes the supply-limit relation: the offered capacity bar p_t bounds cleared generation p_t at each time."},{"object_id":"v141-c-R017-C004","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C004 formalizes the clearing-feasibility conjunction of (2.31c) and (2.31f): computing-capacity bounds on d_t plus rec/snd virtual flows, and capacity bounds on each virtual flow delta_v."},{"object_id":"v141-c-R017-C005","node_ids":["bidding.demand","bidding.supply","clearing.social_welfare"],"edge_ids":["v141-c-R017-E001","v141-c-R017-E002"],"rationale":"C005 formalizes the time-node power balance (2.31b) inside clearing; it relates the demand and supply variables bound through E001 and E002, together with internal virtual flows."}],"revision_requests":["B re-extraction: resolve the demand term in (2.31a). Confirm whether the intended expression is \\sum_{t\\in T}\\alpha^{d}_t d_t or exactly \\sum_{j\\in D}\\alpha^{d}_j d_j; if j\\in D is intended, supply the definition/domain of D, d_j, and \\alpha^{d}_j in the temporal setting. This blocks formalization of C003.","B re-extraction: define \\bar d^{max}_t for the temporal setting or confirm that it is the time-indexed analogue of \\bar d^{max}_n in (2.28). The temporal text around (2.31c) does not define it.","B re-extraction: resolve the virtual-link capacity notation. Evidence v141-b-g02-e034 prints \\bar\\delta_t while (2.31f) prints \\bar\\delta_v; confirm the intended per-link capacity symbol for v\\in V.","C.1 clarification: the frozen graph has no virtual-link node/edge; delta_v, alpha^delta_v, and bar delta_v are bound only to clearing.social_welfare as internal clearing objects. If virtual-link entities are to be represented explicitly, C.1 must add them; no V/E change is made here."]},"C2_delivery":{"raw_sha256":"f2b214dab484fd1f4c5d6a0e07994577dbe6056262106156ffbb2f87abf6ed26","delivery_payload_sha256":"27431e7adb8df6372906b7da7a7d498d081e9c2d9023ca7f13bd58589944b211","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.2.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.3.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.4.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.5.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.6.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"fb88f0211164333e753c41a66162a4e11b8ec6452efb6a3d5735ed1dc73f0a89","scientific_correctness_verified":false}},"quarantined_references":[]}});
